Seg segs[MAXN];
int n;

int used[MAXN];
Comp comps[MAXN];
int compCnt;

int minx(int a, int b){ return a < b ? a : b; }
int maxx(int a, int b){ return a > b ? a : b; }

int overlap1d(int a1, int a2, int b1, int b2) {
    if (a1 > a2) { int t = a1; a1 = a2; a2 = t; }
    if (b1 > b2) { int t = b1; b1 = b2; b2 = t; }
    return !(a2 < b1 || b2 < a1);
}

int connected(int i, int j) {
    Seg a = segs[i], b = segs[j];

    int av = (a.x1 == a.x2);
    int ah = (a.y1 == a.y2);
    int bv = (b.x1 == b.x2);
    int bh = (b.y1 == b.y2);

    if (av && bv) {
        if (a.x1 != b.x1) return 0;
        return overlap1d(a.y1, a.y2, b.y1, b.y2);
    }
    if (ah && bh) {
        if (a.y1 != b.y1) return 0;
        return overlap1d(a.x1, a.x2, b.x1, b.x2);
    }
    if (av && bh) {
        int x = a.x1, y = b.y1;
        int amin = minx(a.y1, a.y2), amax = maxx(a.y1, a.y2);
        int bmin = minx(b.x1, b.x2), bmax = maxx(b.x1, b.x2);
        return (amin <= y && y <= amax && bmin <= x && x <= bmax);
    }
    if (ah && bv) {
        int y = a.y1, x = b.x1;
        int amin = minx(a.x1, a.x2), amax = maxx(a.x1, a.x2);
        int bmin = minx(b.y1, b.y2), bmax = maxx(b.y1, b.y2);
        return (amin <= x && x <= amax && bmin <= y && y <= bmax);
    }
    return 0;
}

void dfs(int u, int cid) {
    used[u] = 1;
    Comp *c = &comps[cid];
    c->idx[c->cnt++] = u;

    Seg s = segs[u];
    int xs[2] = {s.x1, s.x2};
    int ys[2] = {s.y1, s.y2};
    for (int k = 0; k < 2; k++) {
        if (xs[k] < c->x) c->x = xs[k];
        if (xs[k] > c->x + c->w) c->w = xs[k] - c->x;
        if (ys[k] < c->y) c->y = ys[k];
        if (ys[k] > c->y + c->h) c->h = ys[k] - c->y;
    }

    for (int v = 0; v < n; v++) {
        if (!used[v] && connected(u, v)) dfs(v, cid);
    }
}

int cmpComp(const void *A, const void *B) {
    const Comp *a = (const Comp*)A;
    const Comp *b = (const Comp*)B;
    if (a->x != b->x) return a->x - b->x;
    return a->y - b->y;
}

int is_horizontal(Seg s) { return s.y1 == s.y2; }
