            for (int i = 0; i < c->cnt; i++) if (is_vertical(segs[c->idx[i]])) {
                if (segs[c->idx[i]].x1 == c->x) left++;
                else right++;
            }
            if (left == 2) return '4';
            if (right == 2) return '7';
        }
