        int hcnt = 0, vcnt = 0;
        for (int i = 0; i < c->cnt; i++) {
            if (is_horizontal(segs[c->idx[i]])) hcnt++;
            if (is_vertical(segs[c->idx[i]])) vcnt++;
        }
        if (hcnt == 3 && vcnt == 2) {
            int left = 0, right = 0;
            int topv = 0, botv = 0;
            int ymid = c->y + height / 2;
            for (int i = 0; i < c->cnt; i++) if (is_vertical(segs[c->idx[i]])) {
                Seg s = segs[c->idx[i]];
                int sy1 = minx(s.y1, s.y2), sy2 = maxx(s.y1, s.y2);
                if (s.x1 == c->x) left++;
                else right++;
                if (sy2 <= ymid) topv++;
                if (sy1 >= ymid) botv++;
            }
            if (left == 1 && right == 1) return '8';
            for (int i = 0; i < c->cnt; i++) if (is_vertical(segs[c->idx[i]])) {
                Seg s = segs[c->idx[i]];
                int sy1 = minx(s.y1, s.y2), sy2 = maxx(s.y1, s.y2);
                if (s.x1 == c->x && sy1 == c->y) return '6';
                if (s.x1 != c->x && sy2 == c->y + height) return '9';
            }
        }
    }

    if (c->cnt == 2) {
        int diagLike = 0;
        for (int i = 0; i < c->cnt; i++) {
            Seg s = segs[c->idx[i]];
            if (!(is_horizontal(s) || is_vertical(s))) diagLike++;
        }
        if (diagLike == 2) return '*';
    }

    return '?';
}

long long parse_expr(const char *s, int *p);

long long parse_number(const char *s, int *p) {
    long long v = 0;
    while (isdigit((unsigned char)s[*p])) {
        v = v * 10 + (s[*p] - '0');
        (*p)++;
    }
    return v;
}

long long parse_factor(const char *s, int *p) {
    return parse_number(s, p);
}

long long parse_term(const char *s, int *p) {
    long long v = parse_factor(s, p);
    while (s[*p] == '*') {
        (*p)++;
        v *= parse_factor(s, p);
    }
    return v;
}

long long parse_expr(const char *s, int *p) {
    long long v = parse_term(s, p);
    while (s[*p] == '+' || s[*p] == '-') {
        char op = s[*p];
        (*p)++;
        long long t = parse_term(s, p);
        if (op == '+') v += t;
        else v -= t;
    }
    return v;
}

