// Evaluate expression respecting operator precedence (* before +,-)
int evaluate(const string &expr) {
    // First pass: handle multiplication
    vector<int> nums;
    vector<char> ops;
    int i = 0;
    int n = expr.size();
    while (i < n) {
        if (isdigit(expr[i])) {
            int num = 0;
            while (i < n && isdigit(expr[i])) {
                num = num * 10 + (expr[i] - '0');
                i++;
            }
            nums.push_back(num);
        } else if (expr[i] == '*' || expr[i] == '+' || expr[i] == '-') {
            ops.push_back(expr[i]);
            i++;
        } else {
            i++; // skip spaces or other
        }
    }
    // Handle multiplication
    vector<int> vals;
    vals.push_back(nums[0]);
    for (int j = 0; j < (int)ops.size(); j++) {
        if (ops[j] == '*') {
            int last = vals.back();
            vals.pop_back();
            vals.push_back(last * nums[j+1]);
        } else {
            vals.push_back(nums[j+1]);
        }
    }
    // Now handle + and - left to right
    int result = vals[0];
    int idx = 0;
    for (int j = 0; j < (int)ops.size(); j++) {
        if (ops[j] == '+') {
            idx++;
            result += vals[idx];
        } else if (ops[j] == '-') {
            idx++;
            result -= vals[idx];
        }
    }
    return result;
}

