import java.util.*;
import java.math.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        List<String> lines = new ArrayList<>();
        while (sc.hasNextLine()) {
            String line = sc.nextLine();
            lines.add(line);
        }

        // Each character is 3 wide, 5 tall, separated by 1 space column
        // Rows: 0,1,2,3,4 (5 rows)
        int height = lines.size(); // should be 5
        if (height == 0) return;
        int width = lines.get(0).length();
        // Normalize lines to same width
        for (int i = 0; i < lines.size(); i++) {
            String s = lines.get(i);
            while (s.length() < width) s += " ";
            lines.set(i, s);
        }

        // Characters occupy columns: 0..2, 4..6, 8..10, etc. (width 3, gap 1)
        StringBuilder expr = new StringBuilder();
        int charWidth = 3;
        int gap = 1;
        int numChars = (width + gap) / (charWidth + gap);

        for (int c = 0; c < numChars; c++) {
            int startCol = c * (charWidth + gap);
            char recognized = recognizeChar(lines, startCol, charWidth);
            expr.append(recognized);
        }

        String expression = expr.toString().trim();
        BigInteger result = evaluate(expression);
        System.out.println(result);
    }

    static char recognizeChar(List<String> lines, int startCol, int w) {
        // Extract the 5x3 block
        // Use 7-segment: top, top-left, top-right, middle, bot-left, bot-right, bottom
        boolean top = hasHoriz(lines, 0, startCol, w);
        boolean mid = hasHoriz(lines, 2, startCol, w);
        boolean bot = hasHoriz(lines, 4, startCol, w);
        boolean tl = hasVert(lines, 1, startCol);
        boolean tr = hasVert(lines, 1, startCol + w - 1);
        boolean bl = hasVert(lines, 3, startCol);
        boolean br = hasVert(lines, 3, startCol + w - 1);

        int code = (top?64:0)|(tl?32:0)|(tr?16:0)|(mid?8:0)|(bl?4:0)|(br?2:0)|(bot?1:0);
        Map<Integer,Character> map = new HashMap<>();
        map.put(0b1110111, '0'); map.put(0b0010010, '1'); map.put(0b1011101, '2');
        map.put(0b1011011, '3'); map.put(0b0111010, '4'); map.put(0b1101011, '5');
        map.put(0b1101111, '6'); map.put(0b1010010, '7'); map.put(0b1111111, '8');
        map.put(0b1111011, '9'); map.put(0b0001000, '-'); map.put(0b0001001, '+');
        map.put(0b0000001, '.');
        return map.getOrDefault(code, '?');
    }

    static boolean hasHoriz(List<String> lines, int row, int startCol, int w) {
        if (row >= lines.size()) return false;
        String line = lines.get(row);
        for (int i = startCol+1; i < startCol+w-1 && i < line.length(); i++)
            if (line.charAt(i) == '-') return true;
        return false;
    }

    static boolean hasVert(List<String> lines, int row, int col) {
        if (row >= lines.size()) return false;
        String line = lines.get(row);
        if (col >= line.length()) return false;
        return line.charAt(col) == '|';
    }

    static BigInteger evaluate(String expr) {
        // Parse and evaluate with precedence
        int[] pos = {0};
        return parseExpr(expr, pos);
    }

    static BigInteger parseExpr(String expr, int[] pos) {
        BigInteger result = parseTerm(expr, pos);
        while (pos[0] < expr.length() && (expr.charAt(pos[0]) == '+' || expr.charAt(pos[0]) == '-')) {
            char op = expr.charAt(pos[0]++);
            BigInteger t = parseTerm(expr, pos);
            result = op == '+' ? result.add(t) : result.subtract(t);
        }
        return result;
    }

    static BigInteger parseTerm(String expr, int[] pos) {
        BigInteger result = parseNum(expr, pos);
        while (pos[0] < expr.length() && expr.charAt(pos[0]) == '.') {
            pos[0]++;
            BigInteger t = parseNum(expr, pos);
            result = result.multiply(t);
        }
        return result;
    }

    static BigInteger parseNum(String expr, int[] pos) {
        StringBuilder sb = new StringBuilder();
        if (pos[0] < expr.length() && expr.charAt(pos[0]) == '-') { sb.append('-'); pos[0]++; }
        while (pos[0] < expr.length() && Character.isDigit(expr.charAt(pos[0]))) sb.append(expr.charAt(pos[0]++));
        return new BigInteger(sb.toString());
    }
}

