        while (i < expr.length()) {
            char c = expr.charAt(i);
            if (Character.isDigit(c)) {
                long num = 0;
                while (i < expr.length() && Character.isDigit(expr.charAt(i))) {
                    num = num * 10 + (expr.charAt(i) - '0');
                    i++;
                }
                nums.add(num);
            } else {
                ops.add(c);
                i++;
            }
        }
        // First pass: multiplication
        List<Long> nums2 = new ArrayList<>();
        List<Character> ops2 = new ArrayList<>();
        nums2.add(nums.get(0));
        for (int j = 0; j < ops.size(); j++) {
            if (ops.get(j) == '*') {
                long last = nums2.remove(nums2.size()-1);
                long prod = last * nums.get(j+1);
                nums2.add(prod);
            } else {
                nums2.add(nums.get(j+1));
                ops2.add(ops.get(j));
            }
        }
        // Second pass: + and -
        long result = nums2.get(0);
        for (int j = 0; j < ops2.size(); j++) {
            if (ops2.get(j) == '+') {
                result += nums2.get(j+1);
            } else {
                result -= nums2.get(j+1);
            }
        }
        return result;
