public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Segment {
        int x1, y1, x2, y2;
        Segment(int x1, int y1, int x2, int y2) {
            this.x1 = x1; this.y1 = y1; this.x2 = x2; this.y2 = y2;
        }
        boolean horizontal() { return y1 == y2; }
        boolean vertical() { return x1 == x2; }
    }

    static class Symbol {
        int minX, maxX, minY, maxY;
        ArrayList<Segment> segs = new ArrayList<>();
    }

    static class DSU {
        int[] p, r;
        DSU(int n) {
            p = new int[n];
            r = new int[n];
            for (int i = 0; i < n; i++) p[i] = i;
        }
        int find(int x) {
            if (p[x] != x) p[x] = find(p[x]);
            return p[x];
        }
        void union(int a, int b) {
            a = find(a); b = find(b);
            if (a == b) return;
            if (r[a] < r[b]) p[a] = b;
            else if (r[a] > r[b]) p[b] = a;
            else { p[b] = a; r[a]++; }
        }
    }

    static boolean overlap1D(int a1, int a2, int b1, int b2) {
        int l = Math.max(Math.min(a1, a2), Math.min(b1, b2));
        int r = Math.min(Math.max(a1, a2), Math.max(b1, b2));
        return l <= r;
    }

    static boolean connected(Segment a, Segment b) {
        if (a.horizontal() && b.horizontal()) {
            if (a.y1 != b.y1) return false;
            return overlap1D(a.x1, a.x2, b.x1, b.x2);
        } else if (a.vertical() && b.vertical()) {
            if (a.x1 != b.x1) return false;
            return overlap1D(a.y1, a.y2, b.y1, b.y2);
        } else {
            Segment h = a.horizontal() ? a : b;
            Segment v = a.horizontal() ? b : a;
            int hx1 = Math.min(h.x1, h.x2), hx2 = Math.max(h.x1, h.x2);
            int vy1 = Math.min(v.y1, v.y2), vy2 = Math.max(v.y1, v.y2);
            return hx1 <= v.x1 && v.x1 <= hx2 && vy1 <= h.y1 && h.y1 <= vy2;
        }
    }

    static char recognize(Symbol s) {
        int h = s.maxY - s.minY;
        int w = s.maxX - s.minX;

        int hc = 0, vc = 0;
        ArrayList<Segment> hs = new ArrayList<>();
        ArrayList<Segment> vs = new ArrayList<>();
        for (Segment seg : s.segs) {
            if (seg.horizontal()) {
                hc++;
                hs.add(seg);
            } else {
                vc++;
                vs.add(seg);
            }
        }

        if (hc == 1 && vc == 0) return '-';
        if (hc == 1 && vc == 1) return '+';
        if (hc == 2 && vc == 0) return '=';
        if (hc == 0 && vc == 1) return '1';

        if (hc == 2 && vc == 1) {
            // likely 4 or 7
            int topY = Integer.MAX_VALUE, midY = Integer.MIN_VALUE;
            Segment top = null, otherH = null;
            for (Segment seg : hs) {
                if (seg.y1 < topY) {
                    topY = seg.y1;
                    top = seg;
                }
            }
            for (Segment seg : hs) if (seg != top) otherH = seg;
            Segment v = vs.get(0);
            if (top != null && otherH != null) {
                if (Math.min(v.y1, v.y2) <= otherH.y1 && otherH.y1 <= Math.max(v.y1, v.y2)) {
                    if (Math.min(v.x1, v.x2) == s.maxX) return '4';
                }
            }
            return '7';
        }

        if (hc == 3 && vc == 0) return '3';

        if (hc == 3 && vc == 1) {
            boolean hasLeftV = false, hasRightV = false;
            for (Segment v : vs) {
                if (v.x1 == s.minX) hasLeftV = true;
                if (v.x1 == s.maxX) hasRightV = true;
            }
            if (hasLeftV) return '5';
            if (hasRightV) return '2';
        }

        if (hc == 2 && vc == 2) {
            boolean left = false, right = false;
            for (Segment v : vs) {
                if (v.x1 == s.minX) left = true;
                if (v.x1 == s.maxX) right = true;
            }
            if (left && right) return '0';
            // 6, 9
            boolean top = false, bottom = false;
            for (Segment hseg : hs) {
                if (hseg.y1 == s.minY) top = true;
                if (hseg.y1 == s.maxY) bottom = true;
            }
            boolean leftV = false, rightV = false;
            for (Segment v : vs) {
                if (v.x1 == s.minX) leftV = true;
                if (v.x1 == s.maxX) rightV = true;
            }
            if (leftV) return '6';
            if (rightV) return '9';
        }

        if (hc == 3 && vc == 2) {
            boolean left = false, right = false;
            for (Segment v : vs) {
                if (v.x1 == s.minX) left = true;
                if (v.x1 == s.maxX) right = true;
            }
            if (left && right) return '8';
        }

        if (hc == 1 && vc == 2) return '*'; // multiplication dot/cross style fallback

        // More robust recognition by classic 7-segment layout
        boolean top = false, mid = false, bottom = false;
        boolean ul = false, ur = false, ll = false, lr = false;

        int yTop = s.minY, yBot = s.maxY, yMid = (s.minY + s.maxY) / 2;
        int xLeft = s.minX, xRight = s.maxX;

        for (Segment seg : hs) {
            int y = seg.y1;
            if (Math.abs(y - yTop) <= Math.abs(y - yMid) && Math.abs(y - yTop) <= Math.abs(y - yBot)) top = true;
            else if (Math.abs(y - yBot) <= Math.abs(y - yMid) && Math.abs(y - yBot) <= Math.abs(y - yTop)) bottom = true;
            else mid = true;
        }
        for (Segment seg : vs) {
            int x = seg.x1;
            int cy = (seg.y1 + seg.y2) / 2;
            boolean leftSide = Math.abs(x - xLeft) <= Math.abs(x - xRight);
            boolean upper = cy * 2 < s.minY + s.maxY;
            if (leftSide && upper) ul = true;
            else if (!leftSide && upper) ur = true;
            else if (leftSide) ll = true;
            else lr = true;
        }

        if (top && bottom && ul && ur && ll && lr && !mid) return '0';
        if (!top && !bottom && !ul && ur && !ll && lr && !mid) return '1';
        if (top && mid && bottom && !ul && ur && ll && !lr) return '2';
        if (top && mid && bottom && !ul && ur && !ll && lr) return '3';
        if (!top && mid && !bottom && ul && ur && !ll && lr) return '4';
        if (top && mid && bottom && ul && !ur && !ll && lr) return '5';
        if (top && mid && bottom && ul && !ur && ll && lr) return '6';
        if (top && !mid && !bottom && !ul && ur && !ll && lr) return '7';
        if (top && mid && bottom && ul && ur && ll && lr) return '8';
        if (top && mid && bottom && ul && ur && !ll && lr) return '9';

        // Multiplication sign often represented by a small x-like shape with 2 diagonals,
        // but input is line segments on grid likely axis-aligned per statement examples.
        // If something remains unknown, assume multiplication operator.
        return '*';
    }

    static long evaluate(String expr) {
        ArrayList<Long> terms = new ArrayList<>();
        ArrayList<Character> ops = new ArrayList<>();

        int i = 0, n = expr.length();
        while (i < n) {
            int j = i;
            while (j < n && Character.isDigit(expr.charAt(j))) j++;
            long val = Long.parseLong(expr.substring(i, j));
            terms.add(val);
            if (j < n) ops.add(expr.charAt(j));
            i = j + 1;
        }

        ArrayList<Long> vals = new ArrayList<>();
        ArrayList<Character> ops2 = new ArrayList<>();
        long cur = terms.get(0);
        for (i = 0; i < ops.size(); i++) {
            char op = ops.get(i);
            long nxt = terms.get(i + 1);
            if (op == '*') cur *= nxt;
            else {
                vals.add(cur);
                ops2.add(op);
                cur = nxt;
            }
        }
        vals.add(cur);

        long res = vals.get(0);
        for (i = 0; i < ops2.size(); i++) {
            char op = ops2.get(i);
            long nxt = vals.get(i + 1);
            if (op == '+') res += nxt;
            else res -= nxt;
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        Segment[] segs = new Segment[n];
        for (int i = 0; i < n; i++) {
            int x1 = fs.nextInt();
            int y1 = fs.nextInt();
            int x2 = fs.nextInt();
            int y2 = fs.nextInt();
            segs[i] = new Segment(x1, y1, x2, y2);
        }

        DSU dsu = new DSU(n);
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (connected(segs[i], segs[j])) dsu.union(i, j);
            }
        }

        HashMap<Integer, Symbol> map = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int r = dsu.find(i);
            Symbol s = map.get(r);
            if (s == null) {
                s = new Symbol();
                s.minX = s.minY = Integer.MAX_VALUE;
                s.maxX = s.maxY = Integer.MIN_VALUE;
                map.put(r, s);
            }
            Segment seg = segs[i];
            s.segs.add(seg);
            s.minX = Math.min(s.minX, Math.min(seg.x1, seg.x2));
            s.maxX = Math.max(s.maxX, Math.max(seg.x1, seg.x2));
            s.minY = Math.min(s.minY, Math.min(seg.y1, seg.y2));
            s.maxY = Math.max(s.maxY, Math.max(seg.y1, seg.y2));
        }

        ArrayList<Symbol> symbols = new ArrayList<>(map.values());
        symbols.sort(Comparator.comparingInt(a -> a.minX));

        StringBuilder expr = new StringBuilder();
        for (Symbol s : symbols) {
            char c = recognize(s);
            if (c == '=') break;
            if (c == '·' || c == 'x' || c == 'X') c = '*';
            expr.append(c);
        }

        long ans = evaluate(expr.toString());
        System.out.println(ans);
    }
